interface LoginView {
  showError(message: string): void;
  navigateToHome(): void;
}

// All logic lives here, with zero dependency on any UI framework
class LoginPresenter {
  constructor(private view: LoginView) {}

  onLoginClicked(email: string, password: string) {
    if (!email.includes("@")) {
      this.view.showError("Invalid email");
      return;
    }
    if (password.length < 8) {
      this.view.showError("Password too short");
      return;
    }
    this.view.navigateToHome();
  }
}

// Testable with a plain fake view — no UI framework, no emulator
const fakeView = { showError: jest.fn(), navigateToHome: jest.fn() };
new LoginPresenter(fakeView).onLoginClicked("bad-email", "short");
expect(fakeView.showError).toHaveBeenCalledWith("Invalid email");
